export function buildExpansion(root){
 const registry=['source-catalog.json','source-catalog-extra.json'].flatMap(name=>JSON.parse(fs.readFileSync(path.join(root,'docs/reporting-library/expansion-150',name),'utf8')));
 const fallback={FI:'Local Financial Close',CO:'Archiving of CO-PA Transaction Data',MM:'Manage Sources of Supply',PP:'Material Staging (with EWM)',SD:'Display Sales Orders - VA03',QM:'Classic Apps for Inspection Planning',PM:'Maintenance Task List Data'};
 const reports=definitions.split('\n').map(line=>{
  const [id,tcode,title,sourceFamily,kind,grain,keyList,fieldList,purpose,risk]=line.split('|');
  const module=id.match(/^[A-Z]+/)[0], keys=keyList.split(','), columns=fieldList.split(',');
  const direct=extraSources.find(x=>x.alias===sourceFamily)||registry.find(x=>x.title.toLowerCase().includes(aliases[sourceFamily].toLowerCase())&&!x.url.includes('BYDESIGN')&&!x.url.includes('BANKING'));
  const source=direct||registry.find(x=>x.title===fallback[module]);
  if(!source)throw Error(`Missing public source context ${id}/${sourceFamily}`);
  const source_evidence=[{...source,scope:direct?'FEATURE_OR_TRANSACTION_CONTEXT_ONLY':'MODULE_CONTEXT_ONLY_IDENTITY_NOT_VERIFIED',layout_verified:false,company_release_verified:false}];
  const selection=`Chọn đúng company/plant/CO area, kỳ hoặc key date và scope của ${title}. Lưu selection variant, layout, language, currency, row limit và extracted_at. ${kind==='RUN_EVIDENCE'?'Chỉ đọc log/kết quả operator cung cấp, không chạy posting hoặc release.':kind==='MASTER_DISPLAY'?'Dùng chế độ display; lưu validity/version trước join giao dịch.':'Chỉ xem hoặc export list, không thực hiện create/change/release.'}`;
  return {id,module,tcode,title,sourceFamily,kind,grain,keys,columns,fields:columns.map(field),purpose,selection,reading:`Một dòng: ${grain}. Thứ tự cột là đề xuất SAVA để thực hành; chưa xác minh SAP original output. Tách header/selection/detail và giữ số0 đầu. Các dòng demo có ca thiếu giá trị, locale khác và khóa trùng để thử control.`,reconciliation:`${risk} Đối chiếu row count và control total với nguồn cùng phạm vi/kỳ. Nối bằng ${keys.join(' + ')} cùng source_system/client; kiểm cardinality và unmatched. Giữ riêng units/currencies và dòng subtotal; dữ liệu mẫu không có control total từ SAP.`,controls:[risk,'Giữ RAW riêng khỏi CLEAN; preserve reject rows, duplicate keys và source-row IDs.','Không coi field/order/technical name đề xuất là company field catalog.'],control:risk,ifrs:ifrs[module],lineage:`Nguồn công khai xác minh ngữ cảnh → profile ${id} và layout version SAVA → RAW giả định → CLEAN riêng + reject log → control/reconciliation có bằng chứng → mart quản trị.`,status:'AUTHORED_PROPOSED_SCHEMA_PENDING_COMPANY_LAYOUT_AND_SME',mapping_status:direct?'SAP_FEATURE_CONTEXT_TARGET_PENDING':'MODULE_CONTEXT_IDENTITY_PENDING',fiori_app:sourceFamily==='cash'?'F2332':sourceFamily==='inventory'?'F1956':id==='FI24'?'F0731A':null,tcode_identity_status:'CANDIDATE_TARGET_NOT_VERIFIED',tcode_fiori_relation:'NO_EQUIVALENCE_CLAIMED',source_evidence,source_url:source.url,source_edition:source.source_version,target_release:'UNKNOWN',source_layout_status:'NOT_VERIFIED_SAVA_PROPOSED_ORDER',native_export:false,full_sap_catalog_verified:false,owner:module==='FI'?'GL/AP/AR Controller':module==='CO'?'Cost Accountant':module==='MM'?'Procurement / Inventory Controller':module==='PP'?'Production Planner':module==='SD'?'Sales Operations / Revenue Accountant':module==='QM'?'Quality Engineer':'Maintenance Planner',frequency:kind==='MASTER_DISPLAY'?'Khi thay đổi master và tại thời điểm trích xuất':'Ngày/tuần hoặc kỳ closing theo business owner',limits:[direct?'Nguồn chỉ cung cấp ngữ cảnh tính năng, không chứng nhận layout export.':'Chưa xác minh identity T-code từ nguồn trực tiếp; chỉ có module context.',...(id==='QM08'?['Nguồn đánh dấu app deprecated; phải kiểm successor theo target release.']:[]),...(id==='PP06'?['MD05 là classic MRP snapshot; không giả định MRP Live tạo list này.']:[]),...(id==='SD13'?['VKM1 là legacy context; FSCM credit workflow cần kiểm riêng.']:[]),'Edition/release công ty chưa biết; năm triển khai2022 không xác định release.','Tên kỹ thuật, cột ẩn và thứ tự export company chưa xác nhận.']};
 });
 const variants=reports.map(r=>{
  const cases=['BASELINE_SYNTHETIC','MISSING_VALUE_TEST','LOCALE_VARIANT_TEST','DUPLICATE_KEY_TEST'];
  const detail_rows=cases.map((_,i)=>r.fields.map(f=>sample(f,i)));
  setBaseline(r,detail_rows[0]);
  // A deliberate duplicate is never silently removed or counted as a valid new event.
  for(const key of r.keys){let ix=r.columns.indexOf(key);if(ix<0)throw Error(`Key absent ${r.id}: ${key}`);detail_rows[3][ix]=detail_rows[0][ix];}
  const missing=r.fields.findIndex(f=>f.type==='raw_decimal'&&!r.keys.includes(f.key));if(missing>=0)detail_rows[1][missing]='';
  const headers=r.fields.map(f=>f.label);
  const display=[{role:'title',cells:[{text:r.tcode+' — '+r.title,span:headers.length}]},{role:'context',cells:[{text:'SAVA proposed layout · target release UNKNOWN · key date30.09.2026',span:headers.length}]},{role:'header',cells:headers.map(text=>({text,span:1}))},...detail_rows.map(row=>({role:'detail',cells:row.map(text=>({text,span:1}))}))];
  return {id:`EXT-${r.id}-01`,report_id:r.id,tcode:r.tcode,title:r.title,family:'alv_practice',classification:r.kind==='SAVA_DERIVED'?'SAVA_DERIVED_SCHEMA_SYNTHETIC_DATA':'SAVA_PROPOSED_SCHEMA_SYNTHETIC_DATA',source_url:r.source_url,edition_release:r.source_edition,target_release:'UNKNOWN',native_export:false,full_sap_catalog_verified:false,source_labels_complete:false,observed_source_field_count:0,matrix_width:headers.length,contexts:[],fields:r.fields,columns:r.fields,documented_fields:[],detail_rows,flat_rows:detail_rows,fixture_cases:cases,display,limitations:r.limits};
 });
 return {date:'2026-10-13',report_count:reports.length,reports,variants,synthetic_data:true,native_export:false,target_release:'UNKNOWN',scope:'79 additional authored research/practice profiles. All new layouts and field order proposed by SAVA; no native layout acceptance.',sources:[...new Map(reports.flatMap(r=>r.source_evidence).map(s=>[s.url,s])).values()]};
}
function sample(f,i){
 const label=f.label;
 if(label==='Key Date')return '30.09.2026';
 if(f.type==='raw_date')return ['15.09.2026','16.09.2026','17.09.2026','15.09.2026'][i];
 if(/Currency/.test(label))return 'USD';
 if(/Unit/.test(label)&&label!=='Price Unit')return /Capacity|Activity|Duration|Time/.test(label)?'H':'EA';
 if(label==='Price Unit')return '100';
 if(f.type==='raw_decimal')return i===2?'1.234,50':String(100+i*25)+'.00';
 if(label==='Fiscal Year')return '2026';if(label==='Period')return '009';
 if(/Status/.test(label))return ['OPEN','EXCEPTION','REVIEW','DUPLICATE_TEST'][i];
 if(/Flag|Indicator|Managed|Test Run|Blocked|Marked|Released|Counted|Posted|Required|Breakdown/.test(label))return i===1?'':'X';
 if(/Description|Name|Text|Message|Reason/.test(label))return ['SAVA giả định để thực hành','Thiếu dữ liệu cần review','Chuỗi số dùng locale châu Âu','Khóa trùng cố ý để kiểm tra'][i];
 if(label==='Company Code'||label==='Plant')return '1000';if(label==='Controlling Area')return 'A100';
 if(label==='Ledger')return '0L';if(label==='Special Stock')return 'O';if(label==='Price Control')return 'S';
 if(label==='Run ID')return 'SAVA-DEMO-20260930';if(label==='Version')return '000';
 if(label==='Debit Credit')return i%2?'H':'S';
 return /Item|Sequence|Operation/.test(label)?String(i+1).padStart(6,'0'):String(100001+i).padStart(10,'0');
}
